try { HSIMS.wp.t.de = {"gate": {"eyebrow": "Interaktiv · Praxissimulation", "title": "Die Kellerwand von innen abdichten <span>— mit eigenen Händen</span>", "desc": "Die Betonkellerwand des 3D-Musters — gestrahlt, instand gesetzt, vorgedichtet und zweimal mit AQUAFIN-RB400 gegen rückseitig drückendes Wasser beschichtet. Sie führen Lanze, Stemmhammer und Kelle, mischen jedes Material mit seiner Misch- und Reifezeit an, bürsten, spachteln und spritzen die Lagen selbst nach dem Verbrauch des Technischen Merkblatts und halten die Topfzeit ein. Keine Baustelle, kein Risiko: so oft wiederholen, wie Sie möchten.", "foot": "Dreizehn Phasen nach den Technischen Merkblättern von ASOCRET-M30, AQUAFIN-1K und AQUAFIN-RB400; die Bauuhr läuft durch die Wartezeiten.", "m0": "Phasen", "m1": "Materialien anzumischen", "m2": "Topfzeit RB400"}, "eyebrow": "Einsatzbesprechung · Kellerwand, von innen", "title": "Rückseitige Abdichtung <span>mit AQUAFIN-RB400</span>", "sub": "Eine bestehende Betonkellerwand lässt an einer Arbeitsfuge und an Kiesnestern Wasser durch; der alte Anstrich blättert. Von außen kann nicht aufgegraben werden. Die Wand vorbereiten, instand setzen und vordichten, dann zweimal mit AQUAFIN-RB400 auf ≥ 3,0 mm Trockenschicht beschichten — flexibel und rissüberbrückend, gegen drückendes Wasser von der Negativseite (WTA 4-6, bis 0,75 bar).", "brief": ["Die Fläche mit > 400 bar strahlen, die Kiesnester ausstemmen", "Ausbrüche, Ankerlöcher und die aufgestemmte Fuge mit ASOCRET-M30 füllen; Dichtkehle", "Vordichten mit eingebürstetem AQUAFIN-1K, ≤ 1 mm je Arbeitsgang", "Der Fugenstreifen aus AQUAFIN-RB400, 15 cm beidseits", "Erste Lage RB400 mit der Kelle, die zweite nach 3 Stunden — ≥ 3,0 mm Trockenschicht", "Mindestens 3 Tage feucht halten"], "tools": ["HD-Lanze", "Stemmhammer", "Kelle", "Quast", "Zahnkelle", "Spritzgerät", "Schlauch"], "phases": [{"n": "Hochdruckwasserstrahlen", "p": "Die HD-Lanze wählen und den Zeiger auf der Düse halten: Die Fläche wird von oben nach unten mit > 400 bar gestrahlt, bis Anstrich und Kalkfahnen weg sind und der Beton freiliegt, mattfeucht.", "c": "gestrahlt", "done": "Untergrund freigelegt, porenoffen, mattfeucht."}, {"n": "Ausstemmen", "p": "Den Stemmhammer wählen und dabei bleiben: Die Kiesnester werden bis auf den gesunden Beton ausgestemmt, die Ränder rechtwinklig geschnitten.", "c": "ausgestemmt", "done": "Kiesnester bis auf den gesunden Beton ausgestemmt."}, {"n": "Instandsetzung mit ASOCRET-M30", "p": "ASOCRET-M30 anmischen, dann die Kelle führen: Ausbrüche und Ankerlöcher werden gefüllt, die aufgestemmte Arbeitsfuge von unten nach oben bündig verschlossen (3–30 mm in einem Arbeitsgang).", "c": "gefüllt", "done": "Ausbrüche, Ankerlöcher und Fuge bündig gefüllt."}, {"n": "Haftschlämme und Dichtkehle", "p": "AQUAFIN-1K für die Haftschlämme anmischen. Sie entlang der Wand-Boden-Fuge aufbürsten, dann die Dichtkehle aus ASOCRET-M30 frisch in frisch anlegen, Schenkellänge ≥ 4 cm, gerundet.", "c": "Kehle angelegt", "done": "Dichtkehle auf ihrer Haftschlämme angelegt."}, {"n": "Die Kehle bindet ab", "p": "Die zementäre Kehle kann nach ca. 3 Stunden überarbeitet werden. Das angemischte Material in den Eimern steift inzwischen an — frische Ansätze für den nächsten Schritt.", "c": "", "done": ""}, {"n": "Vordichtung mit AQUAFIN-1K", "p": "AQUAFIN-1K anmischen und selbst in die mattfeuchte Wand und den Bodenstreifen einbürsten: mit dem Quast über die Flächen ziehen, porentief, ca. 1,75 kg/m² (≤ 1 mm je Arbeitsgang; mehr als 2 kg/m² in einem Arbeitsgang kann reißen).", "c": "", "done": "Vorgedichtet — die starre Schlämme hält die rückseitige Feuchte von der flexiblen Beschichtung fern."}, {"n": "Überarbeiten nach ca. 6 Stunden", "p": "AQUAFIN-1K wird nach ca. 6 Stunden überarbeitet. Die Bauuhr läuft.", "c": "", "done": ""}, {"n": "Fugenstreifen aus AQUAFIN-RB400", "p": "AQUAFIN-RB400 anmischen (A : B = 1,5 : 1, 3 Minuten, 5 Minuten reifen, aufrühren). Die Zahnkelle über die Arbeitsfuge führen, 15 cm beidseits, auf ≥ 4,0 mm Trockenschicht, dann glätten.", "c": "Streifen aufgebracht", "done": "Arbeitsfuge mit dem Streifen aus RB400 verstärkt."}, {"n": "Erste Lage AQUAFIN-RB400", "p": "Die erste Lage selbst porenfrei über Wand und Bodenstreifen spachteln: eine gleichmäßige Dicke mit der Schichtdickenkelle, ca. 1,8 kg/m² (1,5 mm trocken). Die Topfzeit von 45 Minuten einhalten.", "c": "", "done": "Erste Lage aufgebracht, porenfrei."}, {"n": "Zweiter Arbeitsgang nach ca. 3 Stunden", "p": "Der zweite Arbeitsgang folgt, wenn der erste durch das Überarbeiten nicht mehr beschädigt werden kann — nach ca. 3 Stunden. Einen frischen Ansatz anmischen.", "c": "", "done": ""}, {"n": "Zweite Lage AQUAFIN-RB400", "p": "Die zweite Lage porenfrei über die erste spritzen oder spachteln, ca. 1,8 kg/m²: Die beiden Lagen ergeben ≥ 3,0 mm Trockenschicht für drückendes Wasser (≥ 2,0 mm wären nur Bodenfeuchte).", "c": "", "done": "Zweite Lage aufgebracht — die Dickbeschichtung ist vollständig."}, {"n": "Nachbehandlung", "p": "Den Schlauch wählen und die frische Beschichtung feucht halten; sie ist vor Zugluft, Sonne und direkter Beheizung geschützt. 1 bar nach ca. 16 Stunden, drückendes Wasser nach ≥ 1 Tag.", "c": "feucht gehalten", "done": "Feucht gehalten; belüftet, kein Kondenswasser."}, {"n": "Drei Tage", "p": "≥ 3 Tage feucht gehalten. Die flexible, rissüberbrückende, radondichte Beschichtung hält das drückende Wasser von der Rückseite.", "c": "", "done": ""}], "res_title": "Die Wand ist abgedichtet. <span>Flexibel, rissüberbrückend, radondicht.</span>", "res_sub": "Putz, Fliesen oder eine Beschichtung können folgen, sobald das System erhärtet ist. Die Werkzeuge sofort nach Gebrauch mit Wasser reinigen. Die Technischen Merkblätter und die Sicherheitsdatenblätter beachten."}; _n++; } catch (e) {}
