try { HSIMS.rc.t.de = {"gate": {"eyebrow": "Interaktiv · Praxissimulation", "title": "Das Wasser stoppen und die Wand kristallin abdichten <span>— mit eigenen Händen</span>", "desc": "Die undichte Kellerwand des 3D-Musters: das laufende Wasser mit einem Pfropfen aus FIX-20-T innerhalb seiner zwei Minuten Topfzeit gestoppt, die Fuge aufgestemmt und auf einer Haftschlämme aus AQUAFIN-IC mit ASOCRET-IM gefüllt, die Hohlkehle, dann zwei Lagen AQUAFIN-IC mit 1,5 kg/m² in den mattfeuchten Beton eingebürstet — Sie führen die Werkzeuge, mischen mit den Reifezeiten an, bürsten die Lagen selbst und lassen die Kristalle wachsen.", "foot": "Elf Phasen nach den Technischen Merkblättern von FIX-20-T, ASOCRET-IM und AQUAFIN-IC; die Bauuhr läuft durch die Wartezeiten.", "m0": "Phasen", "m1": "Materialien anzumischen", "m2": "Topfzeit FIX-20-T"}, "eyebrow": "Einsatzbesprechung · Kellerwand, rückseitig drückendes Wasser", "title": "Kristalline Abdichtung von innen <span>mit AQUAFIN-IC</span>", "sub": "Grundwasser drückt durch eine Arbeitsfuge der Betonkellerwand: Die Fuge ist undicht, Kalk wird ausgewaschen, an ihrem Fuß läuft das Wasser ein. Von außen kann nicht aufgegraben werden. Das Wasser stoppen, die Fuge aufstemmen und füllen, die Kehle anlegen, dann zwei Lagen AQUAFIN-IC in den mattfeuchten Beton einbürsten: Die Kristalle wachsen in die Kapillaren und halten das drückende Wasser zurück — bis 1,5 bar von der Negativseite.", "brief": ["Beide Wände mit > 400 bar strahlen; die Fuge 20 × 25 mm aufstemmen; die Leckstelle schwalbenschwanzförmig ausstemmen", "Mattfeucht vornässen — keine Pfützen", "Das laufende Wasser mit FIX-20-T stoppen, von Hand eingedrückt und bis zum Erhärten gehalten", "Haftschlämme aus AQUAFIN-IC, frisch in frisch mit ASOCRET-IM füllen; Hohlkehle ca. 4 cm", "Zwei Lagen AQUAFIN-IC, insgesamt 1,5 kg/m² für drückendes Wasser", "≥ 3 Tage feucht halten, belüftet"], "tools": ["HD-Lanze", "Stemmhammer", "Schlauch", "Hand / Pfropfen", "Quast", "Kelle"], "phases": [{"n": "Hochdruckwasserstrahlen", "p": "Die HD-Lanze wählen und den Zeiger auf der Düse halten: Die Rückwand und die rechte Wand werden von oben nach unten mit > 400 bar gestrahlt, bis der Beton porenoffen und saugfähig ist.", "c": "gestrahlt", "done": "Untergrund porenoffen, frei von haftungsmindernden Stoffen."}, {"n": "Aufstemmen und Schwalbenschwanz", "p": "Den Stemmhammer wählen und dabei bleiben: Die Arbeitsfuge wird 20 mm breit und 25 mm tief aufgestemmt; wo das Wasser austritt, wird die Öffnung für den Pfropfen schwalbenschwanzförmig ausgestemmt.", "c": "aufgestemmt", "done": "Fuge 20 × 25 mm aufgestemmt, die Leckstelle schwalbenschwanzförmig."}, {"n": "Vornässen", "p": "Den Schlauch wählen und Wände und Boden mit sauberem Wasser anfeuchten: zum Zeitpunkt der Verarbeitung mattfeucht, keine Pfützen. Wiederholtes Befeuchten fördert das Wachstum der Kristalle.", "c": "vorgenässt", "done": "Mattfeucht, keine Pfützen."}, {"n": "Die Leckstelle verschließen", "p": "Eine kleine Menge FIX-20-T anmischen. Den Zeiger auf der Leckstelle halten: Der Pfropfen wird von Hand in die schwalbenschwanzförmige Öffnung gedrückt und bis zum Erhärten gehalten — nach 1–2 Minuten, mit spürbarer Erwärmung. Innerhalb der Topfzeit von 2 Minuten!", "c": "verschlossen", "done": "Das Wasser ist gestoppt. FIX-20-T erstarrt auch unter Wasser und quillt gegen den Beton an."}, {"n": "Fuge schlämmen und füllen", "p": "AQUAFIN-IC und ASOCRET-IM anmischen. Die Haftschlämme aus IC in die aufgestemmte Fuge einbürsten, dann frisch in frisch bündig mit IM füllen, bis 10 mm je Arbeitsgang (ca. 1,3 kg je Meter bei 20 × 25 mm).", "c": "gefüllt", "done": "Fuge und Riss bündig gefüllt auf einer Haftschlämme aus AQUAFIN-IC."}, {"n": "Hohlkehle", "p": "Quast und Kelle entlang der Wand-Boden-Fuge und die Ecke hinauf führen: der Untergrund mit AQUAFIN-IC geschlämmt, ASOCRET-IM frisch in frisch mit einer Schenkellänge von ca. 4 cm aufgebracht, gerundet.", "c": "Kehle angelegt", "done": "Hohlkehle angelegt — Teil des kristallinen Systems."}, {"n": "Nach ca. 1–3 Stunden", "p": "Nach ca. 1–3 Stunden wird der frische Mörtel mit AQUAFIN-IC überarbeitet. Die Ansätze in den Eimern sind angesteift — frisch anmischen.", "c": "", "done": ""}, {"n": "Erste Lage AQUAFIN-IC", "p": "AQUAFIN-IC anmischen und die erste Lage selbst in den mattfeuchten Beton einbürsten — Wand, Bodenstreifen, über die gefüllte Fuge und die frische Kehle: gleichmäßig, sorgfältig eingearbeitet, porenfrei, ca. 0,75 kg/m².", "c": "", "done": "Erste Lage eingebürstet."}, {"n": "Zweite Lage, frisch in klebrig", "p": "Die zweite Lage aufbürsten, solange die erste noch klebrig ist und nicht ausgetrocknet: ca. 0,75 kg/m² mehr — 1,5 kg/m² in zwei Lagen für aufstauendes und drückendes Wasser.", "c": "", "done": "Zweite Lage aufgebracht; ein Austrocknen der ersten wurde vermieden."}, {"n": "Nachbehandlung", "p": "Den Schlauch wählen: Jutebahnen werden aufgehängt und die Beschichtung feucht gehalten, der Raum belüftet — kein Kondenswasser, keine direkte Beheizung. Die Kristalle wachsen in die Kapillaren.", "c": "feucht gehalten", "done": "Feucht gehalten und belüftet."}, {"n": "Drei Tage", "p": "≥ 3 Tage feucht gehalten. Begehbar nach ca. 5 Stunden; drückendem Wasser standhaltend nach ≥ 7 Tagen.", "c": "", "done": ""}], "res_title": "Die Wand ist trocken. <span>Die Kristalle halten das drückende Wasser zurück.</span>", "res_sub": "Rückseitig drückendes Wasser bis 1,5 bar; Risse bis 0,4 mm heilen aus, wenn Wasser sie erreicht. Bewegungs- und Anschlussfugen erhalten das ASO-Dichtband-System. Die Technischen Merkblätter und die Sicherheitsdatenblätter beachten."}; _n++; } catch (e) {}
